
-- Presentation content for the composed desk. Keep IDs, schedules, states, revisions and
-- edge-case records identical to the prior rich-workflow fixture.
UPDATE service_requests AS request
SET title = content.title,
    purpose = content.purpose
FROM (VALUES
  ('cedar-01', 'Volunteer orientation in Maple Room', 'Walk the team through opening, room setup, and sign-in.'),
  ('cedar-02', 'Food pantry intake training', 'Practice check-in and confirm which forms are available at reception.'),
  ('cedar-03', 'Winter arts program planning', 'Agree on table placement and quiet space for the family sessions.'),
  ('cedar-04', 'After-school robotics practice', 'Check power access and reserve a clear aisle between the work tables.'),
  ('cedar-05', 'Caregiver evening meetup', 'Arrange seats in a circle and leave space beside the entrance for mobility aids.'),
  ('cedar-06', 'Neighborhood seed exchange', 'Confirm table allocations and access to the supply cabinet.'),
  ('cedar-07', 'Sunday repair café setup', 'Lay out the tool stations and check the power outlets.'),
  ('cedar-08', 'Reading room volunteer briefing', 'Review the closing checklist and confirm where to return the keys.'),
  ('cedar-09', 'Community kitchen orientation', 'Walk the kitchen team through storage, cleaning and room access.'),
  ('cedar-10', 'Printmaking workshop setup', 'Protect the tables and check the drying racks before supplies arrive.'),
  ('cedar-11', 'Garden committee winter meeting', 'Agree on spring work dates and review the seed inventory.'),
  ('cedar-12', 'Neighborhood orchestra rehearsal', 'Arrange music stands and check access for the larger instruments.'),
  ('cedar-13', 'Library reading mentors', 'Pair volunteers and prepare materials for the first reading session.'),
  ('cedar-14', 'First aid workshop', 'Make space for demonstration mats and confirm the room opening time.'),
  ('cedar-15', 'Winter coat collection sorting', 'Set aside space for incoming boxes and sort donations by size.'),
  ('cedar-16', 'Open studio facilitator briefing', 'Assign welcome and cleanup roles before opening the studio.'),
  ('cedar-17', 'Housing advice drop-in setup', 'Set up a private table for conversations away from the entrance.'),
  ('cedar-18', 'Youth theater cast meeting', 'Read through the rehearsal calendar and confirm collection times.'),
  ('cedar-19', 'Community choir rehearsal', 'Arrange the chairs for rehearsal and check that the piano is available.'),
  ('cedar-20', 'Gallery access and arrival planning', 'Review wheelchair access, mark an unobstructed route from reception, and brief volunteers before the public workshop.'),
  ('cedar-21', 'Materials and safety briefing', 'Lay out training materials and review the equipment checklist with the volunteer leads.'),
  ('cedar-22', 'Community film screening rehearsal', 'Check captions, sound and the seating plan before opening the doors.'),
  ('cedar-23', 'Urban food growing workshop', 'Set out soil and seed trays and confirm water is available in the room.'),
  ('cedar-24', 'Family reading night', 'Arrange a quiet reading area and keep the front aisle clear for late arrivals.'),
  ('cedar-25', 'Winter shelter volunteer handover', 'Review shift responsibilities and pass on the room access instructions.'),
  ('cedar-26', 'Saturday bicycle clinic', 'Set out stands and leave the main route clear for bicycles.'),
  ('cedar-27', 'Community garden tool repair', 'Check the workbench and separate tools awaiting parts.'),
  ('cedar-28', 'Book exchange setup', 'Arrange books by age range and confirm where spare boxes can go.'),
  ('cedar-29', 'Local history workshop', 'Set out the archive copies and leave room for people to look through them.'),
  ('cedar-30', 'Warm meals volunteer briefing', 'Confirm serving order and who will take the next delivery.'),
  ('cedar-31', 'Parent and toddler story hour', 'Move spare tables and make a clear space for floor seating.'),
  ('cedar-32', 'Public health information session', 'Arrange a quiet area for private questions after the session.'),
  ('cedar-33', 'Community sewing class', 'Set up extension leads and a separate table for fabric cutting.'),
  ('cedar-34', 'After-school art club', 'Set out washable covers and confirm where work can dry.'),
  ('cedar-35', 'Library friends committee', 'Prepare a room for the monthly budget discussion.'),
  ('cedar-36', 'Neighborhood map workshop', 'Reserve table space for the printed maps and marker sets.'),
  ('cedar-37', 'Senior technology help and advice', 'Check Wi-Fi access and prepare seats near power outlets.'),
  ('cedar-38', 'Spring fundraiser planning', 'Assign volunteer roles and check the proposed room layout.'),
  ('cedar-39', 'Food pantry delivery briefing', 'Confirm the delivery route and reserve a clear space beside reception.'),
  ('cedar-40', 'Community language exchange', 'Place the chairs in small groups and keep the front desk informed.'),
  ('cedar-41', 'School supplies sorting and packing', 'Set aside tables for sorting donated supplies.'),
  ('cedar-42', 'Family pottery demonstration', 'Cover the tables and confirm handwashing access.'),
  ('cedar-43', 'Chess club practice evening', 'Arrange paired tables and reserve two seats near the door.'),
  ('cedar-44', 'Community room maintenance', 'Make room for staff to inspect fixtures and move the folding chairs.'),
  ('cedar-45', 'Music tutor planning session', 'Reserve a quiet room and confirm instrument storage.'),
  ('cedar-46', 'New volunteer welcome and introductions', 'Share the welcome materials and check room access for the group.'),
  ('cedar-47', 'Winter craft table setup', 'Sort donated supplies and prepare the larger work tables.'),
  ('cedar-48', 'Reading group discussion', 'Prepare a circle of seats and set out the reading copies.'),
  ('birch-01', 'Gallery access and arrival planning', 'Confirm access with the Birch venue team.')
) AS content(id, title, purpose)
WHERE request.id = content.id;
